export function beginTrick(kind: TurkeyTailTrickKind, x: number, facing: 1 | -1): TurkeyTailTrick {
  const anim: TrickAnim =
    kind === "trametes"
    ? "sit"
    : kind === "pore"
      ? "play"
      : kind === "bracket"
        ? "talk"
        : kind === "band"
          ? "talk"
          : kind === "leathery"
            ? "sit"
              : "sit";
  return {
    kind: kind,
    phase: kind === "trametes" ? "hold" : "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}


  export function trametesPose(t) {
    const breath = Math.sin(t * 0.14) + 0.051 * Math.sin(t * 0.46);
    const grit = Math.abs(Math.sin(t * 0.25));
    return {
      lift: 0.015 + grit * 0.013,
      rot: -0.44 + breath * 0.54,
    };
  }

  export function releasePose(t) {
    const u = Math.max(0, Math.min(1, t / RELEASE_S));
    return { lift: 0.015 * (1 - Math.sin(u * Math.PI * 0.5)), rot: -0.44 * (1 - u) };
  }

  export function porePose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.pore));
    if (u < 0.12) {
      const s = smoothstep(u / 0.12);
      return { x: fromX, lift: s * -0.028, rot: s * 1.8 * facing, anim: "sit" as TrickAnim };
    }
    if (u < 0.72) {
      const s = (u - 0.12) / 0.6;
      const bite = Math.sin(s * Math.PI * 4.8);
      const deepen = smoothstep(s);
      return {
        x: fromX + facing * deepen * 0.014,
        lift: -0.04 - Math.abs(bite) * 0.028 - deepen * 0.02,
        rot: facing * (2.2 + bite * 3.6),
        anim: "talk" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.72) / 0.28);
    return {
      x: fromX + facing * 0.01 * (1 - s),
      lift: -0.018 * (1 - s),
      rot: facing * (0.8 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
